        const energy = m.squaredNorm();
        const epsilon = 1e-12;
        const stability = if (energy > epsilon) @abs(m.scalar) / (energy + epsilon) else 0.0;
        const is_stable = stability >= self.threshold;

        var vector_state: u8 = 0;
        if (m.vector[0] > 0.0) vector_state |= 1;
        if (m.vector[1] > 0.0) vector_state |= 2;
        if (m.vector[2] > 0.0) vector_state |= 4;

        const implies = (vector_state & self.implication_mask) == self.implication_mask;
        return is_stable and implies;
    }
};

