        return HaarTransformer{ .levels = levels };
    }

    pub fn forward(self: *const HaarTransformer, input: []const f64, alloc: std.mem.Allocator) ![]f64 {
        if (input.len == 0) {
            return alloc.alloc(f64, 0);
        }

        var output = try alloc.dupe(f64, input);
        var current_len = output.len;

        var level: u8 = 0;
        while (level < self.levels) : (level += 1) {
            if (current_len < 2) break;

            const half = current_len / 2;
            const temp = try alloc.alloc(f64, current_len);
            defer alloc.free(temp);

            var i: usize = 0;
            while (i < half) : (i += 1) {
                const a = output[2 * i];
                const b = output[2 * i + 1];
                const sum = a + b;
                const diff = a - b;
                const norm = 0.7071067811865476;
                temp[i] = sum * norm;
                temp[half + i] = diff * norm;
