pub const VSAMemoryUnit = struct {
    dimension: usize,
    histogram_bins: []u32,
    learning_rate: f64,
    allocator: std.mem.Allocator,

    pub fn init(alloc: std.mem.Allocator, dim: usize, lr: f64) !VSAMemoryUnit {
        var bins = try alloc.alloc(u32, dim);
        @memset(bins, 0);
        return VSAMemoryUnit{
            .dimension = dim,
            .histogram_bins = bins,
            .learning_rate = lr,
            .allocator = alloc,
        };
    }

    pub fn deinit(self: *VSAMemoryUnit) void {
        if (self.histogram_bins.len != 0) {
            self.allocator.free(self.histogram_bins);
        }
        self.histogram_bins = &[_]u32{};
    }

    pub fn bindAndSuperpose(self: *VSAMemoryUnit, vector: []const f64) void {
        const len = if (vector.len < self.dimension) vector.len else self.dimension;
        const threshold: f64 = 0.0;

        var i: usize = 0;
        while (i < len) : (i += 1) {
            const v = vector[i];
            if (v > threshold) {
                if (self.histogram_bins[i] < 4294967295) {
                    self.histogram_bins[i] += 1;
                }
            } else if (v < threshold) {
                if (self.histogram_bins[i] > 0) {
                    self.histogram_bins[i] -= 1;
                }
            }
        }
    }

    pub fn recoverSymbol(self: *const VSAMemoryUnit, alloc: std.mem.Allocator) ![]f64 {
        const dim = self.dimension;
        var result = try alloc.alloc(f64, dim);

        var max_bin: u32 = 0;
        for (self.histogram_bins) |b| {
            if (b > max_bin) {
                max_bin = b;
            }
        }

        if (max_bin == 0) {
            @memset(result, 0.0);
            return result;
        }

        var i: usize = 0;
        while (i < dim) : (i += 1) {
            const b = self.histogram_bins[i];
            const nb = @as(f64, @floatFromInt(b)) / @as(f64, @floatFromInt(max_bin));
            result[i] = nb * 2.0 - 1.0;
        }

        return result;
    }
};

