    }

    pub fn bindAndSuperpose(self: *VSAMemoryUnit, vector: []const f64) void {
        const len = if (vector.len < self.dimension) vector.len else self.dimension;
        const threshold: f64 = 0.0;

        var i: usize = 0;
        while (i < len) : (i += 1) {
            const v = vector[i];
            if (v > threshold) {
                if (self.histogram_bins[i] < 4294967295) {
                    self.histogram_bins[i] += 1;
                }
            } else if (v < threshold) {
                if (self.histogram_bins[i] > 0) {
                    self.histogram_bins[i] -= 1;
                }
            }
        }
    }

    pub fn recoverSymbol(self: *const VSAMemoryUnit, alloc: std.mem.Allocator) ![]f64 {
        const dim = self.dimension;
        var result = try alloc.alloc(f64, dim);

        var max_bin: u32 = 0;
        for (self.histogram_bins) |b| {
            if (b > max_bin) {
                max_bin = b;
            }
        }

        if (max_bin == 0) {
            @memset(result, 0.0);
            return result;
        }

        var i: usize = 0;
        while (i < dim) : (i += 1) {
            const b = self.histogram_bins[i];
            const nb = @as(f64, @floatFromInt(b)) / @as(f64, @floatFromInt(max_bin));
            result[i] = nb * 2.0 - 1.0;
        }

        return result;
    }
};

pub const KonigGraphTopology = struct {
    adjacency_list: std.ArrayList(std.ArrayList(usize)),
    allocator: std.mem.Allocator,

    pub fn init(alloc: std.mem.Allocator, node_count: usize) !KonigGraphTopology {
        var list = try std.ArrayList(std.ArrayList(usize)).initCapacity(alloc, node_count);
        errdefer {
            var j: usize = 0;
            while (j < list.items.len) : (j += 1) {
                list.items[j].deinit();
            }
            list.deinit();
        }

        var i: usize = 0;
        while (i < node_count) : (i += 1) {
            var inner = std.ArrayList(usize).init(alloc);
            errdefer inner.deinit();
            try list.append(inner);
            errdefer {} = {};
        }

        return KonigGraphTopology{
            .adjacency_list = list,
            .allocator = alloc,
        };
    }

    pub fn deinit(self: *KonigGraphTopology) void {
        var i: usize = 0;
        while (i < self.adjacency_list.items.len) : (i += 1) {
            self.adjacency_list.items[i].deinit();
        }
        self.adjacency_list.deinit();
    }

    pub fn addEdge(self: *KonigGraphTopology, from: usize, to: usize) !void {
        if (from >= self.adjacency_list.items.len) return error.IndexOutOfRange;
        try self.adjacency_list.items[from].append(to);
    }

    pub fn nodeCount(self: *const KonigGraphTopology) usize {
        return self.adjacency_list.items.len;
    }
};

pub const IntegratedJaideSystem = struct {
    core_node: JaideNode,
    haar_processor: HaarTransformer,
    vsa_memory: VSAMemoryUnit,
    topology: KonigGraphTopology,
    allocator: std.mem.Allocator,

    pub fn init(alloc: std.mem.Allocator, node: JaideNode) !IntegratedJaideSystem {
        var vsa = try VSAMemoryUnit.init(alloc, DEFAULT_VSA_DIMENSION, DEFAULT_VSA_LEARNING_RATE);
        errdefer vsa.deinit();

        var topo = try KonigGraphTopology.init(alloc, DEFAULT_TOPOLOGY_NODE_COUNT);
        errdefer topo.deinit();

        return IntegratedJaideSystem{
            .core_node = node,
            .haar_processor = HaarTransformer.init(3),
            .vsa_memory = vsa,
            .topology = topo,
            .allocator = alloc,
        };
    }

    pub fn deinit(self: *IntegratedJaideSystem) void {
        self.vsa_memory.deinit();
        self.topology.deinit();
    }

    pub fn processSignal(self: *IntegratedJaideSystem, raw_input: []const f64) !Multivector {
        const haar_features = try self.haar_processor.forward(raw_input, self.allocator);
        defer self.allocator.free(haar_features);

        self.vsa_memory.bindAndSuperpose(haar_features);

        const memory_context = try self.vsa_memory.recoverSymbol(self.allocator);
        defer self.allocator.free(memory_context);

        var combined = Multivector.zero();

        if (haar_features.len >= 3) {
            combined.vector = .{
                haar_features[0],
                haar_features[1],
                haar_features[2],
            };
        } else if (haar_features.len > 0) {
            combined.vector[0] = haar_features[0];
        }

        if (memory_context.len > 0) {
            combined.scalar = memory_context[0];
        }

        const node_factor = @as(f64, @floatFromInt(self.topology.nodeCount()));
        const scale = if (node_factor > 0.0) 1.0 + 0.001 * node_factor else 1.0;
        combined = combined.scale(scale);

        return self.core_node.forward(combined);
    }
};

